import math

class GeneratedArenaSkill:
    def __init__(self):
        self.t = 0
        self.tx = 0.5
        self.ty = 0.5

    def compute_action(self, obs):
        self.t += 1
        danger = obs.get("danger", 0)
        esc = obs.get("escape")
        sx, sy = obs["self"]
        if danger is None:
            danger = 0
        if danger >= 0.6 and esc is not None:
            ex, ey = esc
            mx = 1.0 if ex > 0.3 else (-1.0 if ex < -0.3 else 0.0)
            my = 1.0 if ey > 0.3 else (-1.0 if ey < -0.3 else 0.0)
            if mx == 0.0 and my == 0.0:
                if abs(ex) >= abs(ey):
                    mx = 1.0 if ex >= 0 else -1.0
                else:
                    my = 1.0 if ey >= 0 else -1.0
            return {"move": [float(mx), float(my)], "buttons": [], "hold_ms": 0}
        items = obs.get("items") or []
        bx = self.tx
        by = self.ty
        best = 100000.0
        for i in range(6):
            if i < len(items):
                it = items[i]
                dx = it[0] - sx
                dy = it[1] - sy
                d = dx * dx + dy * dy
                if d < best:
                    best = d
                    bx = it[0]
                    by = it[1]
        self.tx = bx
        self.ty = by
        dx = bx - sx
        dy = by - sy
        mx = 0.0
        my = 0.0
        if abs(dx) >= abs(dy):
            mx = 1.0 if dx > 0.01 else (-1.0 if dx < -0.01 else 0.0)
            if mx == 0.0:
                my = 1.0 if dy > 0.01 else (-1.0 if dy < -0.01 else 0.0)
        else:
            my = 1.0 if dy > 0.01 else (-1.0 if dy < -0.01 else 0.0)
            if my == 0.0:
                mx = 1.0 if dx > 0.01 else (-1.0 if dx < -0.01 else 0.0)
        return {"move": [float(mx), float(my)], "buttons": [], "hold_ms": 0}
